export const DIFFICULTIES=['Quiet','Tense','Dangerous','Brutal'];
export function random(seed){let s=seed>>>0;return ()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;};}
export function rollScene(rng,combatOnly=false){const list=SCENES.filter(s=>!combatOnly||!s.safe),sum=list.reduce((a,b)=>a+b.weight,0);let n=rng()*sum;return list.find(s=>(n-=s.weight)<0)||list[0];}
export function rollDifficulty(rng){const v=rng();return v<.4?0:v<.75?1:v<.94?2:3;}
export const CELLS=Array.from({length:6},(_,q)=>[-1,0,1].map(r=>({q,r}))).flat().filter(c=>!(c.q===0&&c.r===-1)&&!(c.q===5&&c.r===1));
export function destinations(run){return CELLS.filter(c=>c.q===run.q+1&&(c.r===run.r||c.r===run.r+(run.q%2?1:-1))).filter(c=>c.q!==3||c.r===0).filter(c=>c.q!==5||c.r===0).filter(c=>!(c.q===2&&c.r===-1));}
export function createRun(ids=['evan','mara','jules'],seed=41){return {schema:1,seed,q:0,r:0,minutes:360,party:ids.map(id=>{const h=HEROES.find(h=>h.id===id)||HEROES[0];return {...h,maxHp:h.hp,level:1,bonus:0,shield:0};}),supplies:{med:2,scrap:0},car:false,scouts:1,history:[],phase:'route',visited:['0,0'],encounter:0};}
export function generateScene(id,difficulty,seed){const type=SCENES.find(s=>s.id===id)||SCENES[0],rng=random(seed);const props=[];for(let i=0;i<type.props+difficulty;i++){const side=i%2?-1:1;props.push({x:260+rng()*390,y:270+side*(95+rng()*55),w:30+rng()*22,h:30+rng()*22,kind:i===0?type.anchor:['crate','tree','pumpkin'][i%3]});}return {type,difficulty,props,seed,enemyCount:type.safe?0:[2,6,12,22][difficulty]+(id==='horde'?4:0),loot:type.loot+difficulty};}
export function createBattle(run,scene){const rng=random(scene.seed+17);const allies=run.party.filter(h=>h.hp>0).map((h,i)=>({...h,x:h.range<120?355:535,y:160+i*48,cool:i*.15,specialCool:3+i*.7,side:'ally',intent:'Approaching',shield:0}));for(const a of allies){if(run.stance==='guard'){if(a.range<120)a.def+=3;a.damage*=.9;}if(run.stance==='press'){a.damage*=1.2;a.def=Math.max(0,a.def-2);}}const enemies=Array.from({length:scene.enemyCount},(_,i)=>{const brute=i%5===4&&scene.difficulty>0;return {id:'z'+i,name:brute?'Brute':'Walker',x:145+rng()*25,y:170+rng()*220,spawnAt:Math.floor(i/4)*5,active:i<4,threat:{},targetId:null,hp:brute?105:48+scene.difficulty*14,maxHp:brute?105:48+scene.difficulty*14,def:brute?5:0,damage:brute?17:9+scene.difficulty*3,range:29,rate:brute?1.4:1,speed:brute?29:38+scene.difficulty*4,cool:rng(),side:'enemy',color:brute?'#ba91a2':'#a9ba82',stun:0,slow:0,marked:0};});return {allies,enemies,scene,time:0,rng,events:[],done:enemies.length===0,won:enemies.length===0,med:run.supplies.med,waves:Math.ceil(scene.enemyCount/4)};}
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function emit(b,type,a,t,amount=0){b.events.push({type,from:{x:a.x,y:a.y},x:t.x,y:t.y,amount,name:a.name,target:t.name,time:b.time});}
export function hit(b,a,t,raw,type='hit'){if(t.hp<=0)return;if(t.side==='enemy'&&a.side==='ally')t.threat[a.id]=(t.threat[a.id]||0)+raw*.45;const absorbed=Math.min(t.shield||0,raw);t.shield=Math.max(0,(t.shield||0)-absorbed);const damage=type==='headshot'?t.hp:Math.min(t.hp,Math.max(0,Math.round((raw-absorbed-t.def)*(t.marked>0?1.5:1))));if(absorbed)emit(b,'shield',a,t,absorbed);t.hp=Math.max(0,t.hp-damage);emit(b,type,a,t,damage);if(t.hp===0)emit(b,'kill',a,t);}
function move(a,t,dt,props){let dx=t.x-a.x,dy=t.y-a.y,l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;for(const p of props){let px=a.x-p.x,py=a.y-p.y,d=Math.hypot(px,py)||1,rad=Math.max(p.w,p.h)/2+18;if(d<rad){dx+=px/d*2;dy+=py/d*2;}}l=Math.hypot(dx,dy)||1;const speed=a.speed*(a.slow>0?.4:1);a.x=Math.max(130,Math.min(780,a.x+dx/l*speed*dt));a.y=Math.max(115,Math.min(445,a.y+dy/l*speed*dt));}
function special(b,a,target){const live=b.enemies.filter(e=>e.hp>0&&e.active).sort((x,y)=>distance(a,x)-distance(a,y));if(a.kind==='heal'){const patient=b.allies.filter(h=>h.hp>0&&h.hp<h.maxHp).sort((x,y)=>x.hp/x.maxHp-y.hp/y.maxHp)[0];if(!patient||b.med<1)return false;b.med--;const n=Math.min(35,patient.maxHp-patient.hp);patient.hp+=n;emit(b,'heal',a,patient,n);}else if(a.kind==='shield'){for(const h of b.allies.filter(h=>h.hp>0))h.shield=Math.max(h.shield,30);for(const e of b.enemies.filter(e=>e.hp>0&&e.active)){e.taunt=a.id;e.tauntUntil=b.time+4;}emit(b,'special',a,a);}else if(a.kind==='slow'){live.slice(0,3).forEach(e=>e.slow=5);emit(b,'special',a,target);}else if(a.kind==='mark'){target.marked=6;emit(b,'special',a,target);}else if(a.kind==='headshot')hit(b,a,target,target.hp,'headshot');else if(a.kind==='stun'){for(const e of live.filter(e=>distance(a,e)<100)){e.stun=2;hit(b,a,e,28,'special');}}else if(a.kind==='blast'){for(const e of live.filter(e=>distance(target,e)<95))hit(b,a,e,40,'special');}else if(a.kind==='scatter'){live.slice(0,4).forEach(e=>hit(b,a,e,24,'special'));}else{hit(b,a,target,a.kind==='execute'?65:45,'special');if(a.kind==='dash')a.shield+=15;}return true;}
export function stepBattle(b,dt){if(b.done)return;dt=Math.min(.1,dt);b.time+=dt;b.events=[];for(const e of b.enemies){if(!e.active&&b.time>=e.spawnAt){e.active=true;emit(b,'wave',e,e);}for(const id in e.threat)e.threat[id]*=Math.pow(.93,dt); }for(const a of [...b.allies,...b.enemies]){if(a.hp<=0||a.active===false)continue;for(const k of ['cool','specialCool','stun','slow','marked'])a[k]=Math.max(0,(a[k]||0)-dt);if(a.stun>0){a.intent='Stunned';continue;}const targets=(a.side==='ally'?b.enemies:b.allies).filter(x=>x.hp>0&&x.active!==false).sort((x,y)=>distance(a,x)-distance(a,y));const t=a.side==='enemy'?aggroTarget(a,targets,b.time):targets[0];if(!t){a.intent='Watching school approach';continue;}const d=distance(a,t);if(d>a.range){a.intent='Closing range';move(a,t,dt,b.scene.props);continue;}a.intent='Attacking '+t.name;if(a.side==='ally'&&a.specialCool<=0&&special(b,a,t)){a.specialCool=9;a.intent=a.special;continue;}if(a.cool<=0){a.cool=a.rate;const head=a.side==='ally'&&a.range>150&&b.rng()<(a.id==='evan'?.12:.025);const crit=!head&&a.side==='ally'&&b.rng()<.15;hit(b,a,t,head?t.hp:(a.damage+(a.bonus||0))*(crit?1.75:1),head?'headshot':crit?'crit':'hit');}}
 b.won=b.enemies.every(e=>e.hp<=0);b.done=b.won||b.allies.every(a=>a.hp<=0)||b.time>=75;
}
export function settleBattle(run,b){for(const h of run.party){const actual=b.allies.find(a=>a.id===h.id);if(actual)h.hp=actual.hp;}run.supplies.med=b.med;const travel=run.car?25:40;run.minutes+=travel+Math.ceil(b.time/2)+b.scene.difficulty*10;run.encounter++;if(b.won){run.supplies.scrap+=b.scene.loot;if(b.scene.type.id==='pharmacy')run.supplies.med+=2;run.phase=run.q===3?'milestone':run.q===5?'won':'reward';}else run.phase=run.party.some(h=>h.hp>0)?'retreated':'lost';if(run.minutes>=1080)run.phase='lost';run.history.push({scene:b.scene.type.name,difficulty:b.scene.difficulty,won:b.won,minutes:run.minutes,hp:run.party.map(h=>h.hp)});return run;}
export function applyReward(run,kind){if(!['reward','milestone','retreated'].includes(run.phase))return false;const alive=run.party.filter(h=>h.hp>0);if(kind==='damage')alive.forEach(h=>{h.bonus+=5;h.level++;});else if(kind==='armor')alive.forEach(h=>{h.def+=2;h.level++;});else if(kind==='med')run.supplies.med+=2;else if(kind==='car'){if(run.supplies.scrap<3)return false;run.supplies.scrap-=3;run.car=true;}else if(kind==='recruit'){if(run.party.length>=5)return false;const h=HEROES.find(h=>!run.party.some(p=>p.id===h.id));run.party.push({...h,maxHp:h.hp,bonus:0,level:1,shield:0});}else return false;run.phase='route';return true;}
export function useMed(run){if(run.supplies.med<=0)return false;const h=run.party.filter(h=>h.hp>0&&h.hp<h.maxHp).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(!h)return false;h.hp+=Math.min(35,h.maxHp-h.hp);run.supplies.med--;return true;}

export function aggroTarget(z,allies,time){
 const alive=allies.filter(a=>a.hp>0);if(!alive.length)return null;
 const taunted=alive.find(a=>a.id===z.taunt);if(taunted&&time<z.tauntUntil){z.targetId=taunted.id;return taunted;}
 const score=a=>(z.threat[a.id]||0)+Math.max(0,320-distance(z,a))+(a.range<120?45:0)+(z.targetId===a.id?25:0);
 const target=alive.sort((a,b)=>score(b)-score(a))[0];z.targetId=target.id;return target;
}
